invitees = ["Cody", "Robin", "Brenda", "James", "Erica", "Nancy", "Chris", "Katie", "Anita", "Paul"]
rsvp_results = {}
for name in invitees:
    phone = name_to_phone[name]
    msgs = apis.phone.search_text_messages(access_token=phone_token, phone_number=phone, sort_by="-created_at", page_limit=20)
    # Find the latest message from the invitee (sender is the invitee)
    latest_from_invitee = None
    for m in msgs:
        if m["sender"]["phone_number"] == phone:
            latest_from_invitee = m
            break
    if latest_from_invitee:
        rsvp_results[name] = latest_from_invitee["message"]
        print(f"{name}: {latest_from_invitee['sent_at']} - {latest_from_invitee['message']}")
    else:
